import{_t as e,it as t,n,rt as r}from"./chunks/framework.BVGGWBQY.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1788651926000}`),a={name:`guide/configuration.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is an environment variable. There is no configuration file, and there is nothing to write to disk.</p><p>The full table with types and defaults is in the <a href="/reference/environment">environment reference</a>; this page is about the choices behind it.</p><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to “Connecting”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://dav.example.net</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_USERNAME</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">you</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_PASSWORD</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">your-app-password</span></span></code></pre></div><p><code>CARDDAV_URL</code> is the root of the server rather than one address book — see <a href="/guide/getting-started#finding-the-url">getting started</a> for what that means per provider. A collection URL works too and limits the server to that one book.</p><p><code>CARDDAV_TOKEN</code> replaces the username and password for a server that wants a bearer token. Setting both is refused at startup rather than resolved by preferring one: which was meant is not knowable from here, and the wrong guess authenticates as somebody else.</p><p><strong>The credentials are deleted from the process environment once read</strong>, before any branch that can exit. They are visible in <code>/proc/&lt;pid&gt;/environ</code> and to child processes until that happens, and the interesting case is the one where startup <em>fails</em> — a missing URL, a malformed one — because that is precisely when somebody attaches an inspector.</p><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p><code>https://</code> always. A plain <code>http://</code> URL to anything that is not loopback <strong>refuses to start</strong>, because it would put the credentials and every contact on the wire in clear on every request. That used to be a warning in this family; a warning on stderr in a stdio deployment is a line nobody ever reads.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_ALLOW_PLAINTEXT</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">   # lifts the refusal, for a trusted network</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_INSECURE_TLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">      # accepts a self-signed certificate</span></span></code></pre></div><p><code>CARDDAV_INSECURE_TLS</code> is scoped to the configured host through an undici dispatcher — <code>NODE_TLS_REJECT_UNAUTHORIZED</code> is never set, so nothing else in the process loses certificate checking.</p><p>Both are read <strong>strictly</strong>: only the exact string <code>true</code>. A switch that lifts a protection must not be turned on by a typo. <code>CARDDAV_READ_ONLY</code> is read the other way — <code>1</code>, <code>yes</code>, <code>TRUE</code> and a stray space all work — because a switch that turns a protection <em>on</em> should not be silently ignored either. The direction decides the strictness, not the variable.</p><h2 id="fencing-the-server-to-named-address-books" tabindex="-1">Fencing the server to named address books <a class="header-anchor" href="#fencing-the-server-to-named-address-books" aria-label="Permalink to “Fencing the server to named address books”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_ADDRESSBOOKS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">work,private</span></span></code></pre></div><p>Anything not named is invisible: not listed, not readable, not writable. An entry can be a full URL, an absolute path, or the collection&#39;s final path segment.</p><p>A <strong>display name is not accepted</strong>, and that is a decision rather than an omission. On a shared address book the display name is chosen by whoever shared it, it is not unique across a principal, and it changes without notice — an allowlist keyed on a mutable, externally controlled string is not an allowlist.</p><p>Two behaviours worth knowing:</p><ul><li><code>list_address_books</code> reports how many books it <strong>withheld</strong>. A listing that silently omitted them would teach the reader they do not exist, and then a perfectly correct id from somewhere else looks like a bug.</li><li>An entry matching <em>two</em> books — only possible for a bare final segment — stops the server rather than resolving to whichever matched first. Either choice would quietly grant access to a collection nobody meant.</li></ul><p>Setting the variable to an empty string is a refusal, not an omission: whoever wrote <code>CARDDAV_ADDRESSBOOKS=</code> in a compose file meant to restrict something.</p><h2 id="read-only" tabindex="-1">Read-only <a class="header-anchor" href="#read-only" aria-label="Permalink to “Read-only”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_READ_ONLY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span></code></pre></div><p>The write tools are <strong>not registered</strong>. They do not appear in <code>tools/list</code> and a call to one answers &quot;tool not found&quot;, byte for byte the same as a name that never existed. Rejecting them at call time instead would advertise a capability the server refuses to provide.</p><h2 id="choosing-the-tools-that-load" tabindex="-1">Choosing the tools that load <a class="header-anchor" href="#choosing-the-tools-that-load" aria-label="Permalink to “Choosing the tools that load”">​</a></h2><p>Seventeen tools is a lot of context on every request, and a model picks worse from a long list than from a short one. Two variables narrow it:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">                            # a curated six</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">list_contacts,get_contact,create_contact</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">list_*</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">                               # one trailing * only</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">delete_contact</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">                        # subtracted from the above</span></span></code></pre></div><p><code>essential</code> selects <code>list_address_books</code>, <code>list_contacts</code>, <code>get_contact</code>, <code>search_contacts</code>, <code>create_contact</code> and <code>update_contact</code> — enough to find a person, read them, add one and correct one, with nothing irreversible in reach and the whole group surface left out. It is an editorial choice, not a mechanical one: &quot;the read tools&quot; is already <code>CARDDAV_READ_ONLY</code> and would add nothing.</p><p>An entry may be an exact tool name or a literal prefix with exactly one trailing <code>*</code>. A star anywhere else is refused. Allow decides what is in; deny is subtracted from whatever allow left.</p><p><strong>A name matching no tool stops the server at startup</strong>, printing the real names. An ignored typo would leave a tool missing from <code>tools/list</code> with nothing pointing at the cause, and nobody traces an absence back to an environment variable.</p><p>Under read-only the two interact in the way you would want: naming a write tool explicitly says <em>read-only is suppressing it</em> rather than <em>no such tool</em>, because the tool does exist and telling the truth about which is the point.</p><h2 id="how-many-contacts-a-listing-returns" tabindex="-1">How many contacts a listing returns <a class="header-anchor" href="#how-many-contacts-a-listing-returns" aria-label="Permalink to “How many contacts a listing returns”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CARDDAV_MAX_CONTACTS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">100</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">    # 1 to 500, the default a listing uses</span></span></code></pre></div><p>Every listing tool also takes a <code>limit</code> argument, which wins. There is a second, harder ceiling behind both: a tool result is capped in bytes, and an answer past it drops whole entries and says how many rather than being truncated mid-string.</p><h2 id="the-dialog-switch" tabindex="-1">The dialog switch <a class="header-anchor" href="#the-dialog-switch" aria-label="Permalink to “The dialog switch”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">ELICITATION</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">false</span></span></code></pre></div><p><strong>Not prefixed</strong>, deliberately, and that is the thing to know about it: one <code>export ELICITATION=false</code> reaches every MCP server in the environment. Because of that a server started with it off prints a line saying so.</p><p>It does not remove the guard. A guarded tool falls back to the two-call token instead of raising a dialog — see <a href="/guide/approval">asking a person</a>. Anything it does not recognise is <strong>fatal</strong>: this is the only variable of the family that defaults to <em>on</em>, so failing open on a typo would leave the dialog running while the operator believed it was off.</p>`,37)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};